insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('2d4a5424-a5ff-5807-bd46-130ec06a6fd9', '0e8a54e6-533a-5a46-830e-098e153d93db', 'multiple_choice', 'What is 3/8 written as a decimal?', '[{"id":"A","text":"0.375"},{"id":"B","text":"0.38"},{"id":"C","text":"0.83"},{"id":"D","text":"3.8"}]'::jsonb, 'foundation', 'question_bank', true)
