insert into public.question_answers (question_id, correct_option, explanation) values ('f275d1fc-6f52-55b9-ba51-14348b73e14f', 'A', 'Collect like terms: 4a − a = 3a and 3b + 2b = 5b, giving 3a + 5b. Terms in a and b can''t be combined with each other.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('7655be1b-aef5-57db-bc95-76cbe22b2788', '8c3a66d3-e9a9-56ee-abc6-2c26be7740d1', 'true_false', 'True or false: substituting x = −2 into x² gives −4.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
