on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('835a5768-a002-5084-b3f0-cfabcede9c48', '8c3a66d3-e9a9-56ee-abc6-2c26be7740d1', 'multiple_choice', 'Expand and simplify (x + 3)(x − 5).', '[{"id":"A","text":"x² − 2x − 15"},{"id":"B","text":"x² + 2x − 15"},{"id":"C","text":"x² − 2x + 15"},{"id":"D","text":"x² − 15"}]'::jsonb, 'standard', 'question_bank', true)
