insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('194d0bf0-905d-530c-af62-2ecc51978510', '8c3a66d3-e9a9-56ee-abc6-2c26be7740d1', 'multiple_choice', 'Solve the simultaneous equations x + y = 10 and x − y = 4.', '[{"id":"A","text":"x = 7, y = 3"},{"id":"B","text":"x = 6, y = 4"},{"id":"C","text":"x = 3, y = 7"},{"id":"D","text":"x = 14, y = −4"}]'::jsonb, 'challenge', 'question_bank', true)
