insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('f3665249-ddcc-5410-af2d-3733018feafb', '3f6a285c-69ea-592e-b2df-a7624cbb82c5', 'true_false', 'True or false: a metaphor compares two things using "like" or "as".', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
