insert into public.question_answers (question_id, correct_option, explanation) values ('e9cff286-a872-54db-87ae-c5f81d8e5333', 'A', 'Hyperbole is deliberate exaggeration for effect. Nobody has literally said something a million times; it shows frustration.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('fc9d823c-019d-5c72-ba51-8e587b726c8d', '3f6a285c-69ea-592e-b2df-a7624cbb82c5', 'multiple_choice', 'What is the term for weather that reflects a character''s mood?', '[{"id":"A","text":"Pathetic fallacy"},{"id":"B","text":"Personification"},{"id":"C","text":"Onomatopoeia"},{"id":"D","text":"Foreshadowing"}]'::jsonb, 'standard', 'question_bank', true)
