insert into public.question_answers (question_id, correct_option, explanation) values ('fc9d823c-019d-5c72-ba51-8e587b726c8d', 'A', 'Pathetic fallacy links the weather or setting to emotions, such as a storm during an argument. It is a type of personification but has its own name.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('bd2d4ce3-25f9-507b-8f38-ccdabf159fe9', '3f6a285c-69ea-592e-b2df-a7624cbb82c5', 'short_answer', 'What is the term for repeating the same consonant sound at the start of nearby words, as in "big bold bears"?', null, 'standard', 'question_bank', true)
