insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('984fa65b-f35a-555c-9a25-c544588c5a58', 'bbd5bcaa-f8d2-57a5-9c35-c2747acf2fa3', 'multiple_choice', 'Which part of a cell contains genetic material and controls the cell''s activities?', '[{"id":"A","text":"Nucleus"},{"id":"B","text":"Cell membrane"},{"id":"C","text":"Cytoplasm"},{"id":"D","text":"Ribosome"}]'::jsonb, 'foundation', 'question_bank', true)
