on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('354e0e73-d333-525d-af07-9481ea8f4f69', '72545cd9-2540-5282-8e5c-da18038e5507', 'multiple_choice', 'Rose black spot is a disease of plants. What kind of pathogen causes it?', '[{"id":"A","text":"A fungus"},{"id":"B","text":"A virus"},{"id":"C","text":"A bacterium"},{"id":"D","text":"A protist"}]'::jsonb, 'challenge', 'question_bank', true)
