insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('92262f86-2cf0-5483-82f2-22fd0b4f6cd7', 'a94514ae-2c74-5a65-95f2-f28a6ce1e701', 'multiple_choice', 'What is the relative charge of an electron?', '[{"id":"A","text":"−1"},{"id":"B","text":"+1"},{"id":"C","text":"0"},{"id":"D","text":"−2"}]'::jsonb, 'foundation', 'question_bank', true)
