insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('37a9ab8c-1080-5b9d-8fa7-894dd6dba0b9', '72a8f72f-3144-534a-8380-4ecd46618339', 'multiple_choice', 'What happens to electrons in a covalent bond?', '[{"id":"A","text":"A pair of electrons is shared between two atoms"},{"id":"B","text":"Electrons are transferred from one atom to another"},{"id":"C","text":"Electrons are destroyed"},{"id":"D","text":"Electrons move freely through a metal"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('37a9ab8c-1080-5b9d-8fa7-894dd6dba0b9', 'A', 'Covalent bonds form between non-metal atoms that share pairs of electrons.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('7ad3e910-d7ce-560d-86c8-7b1ef7afdb17', '72a8f72f-3144-534a-8380-4ecd46618339', 'true_false', 'True or false: metals conduct electricity because they contain delocalised electrons.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('7ad3e910-d7ce-560d-86c8-7b1ef7afdb17', 'A', 'In metallic bonding, outer electrons are delocalised and can move through the structure, carrying charge.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('cd95ddba-2b7a-5cc4-a99f-70633b40d4be', '72a8f72f-3144-534a-8380-4ecd46618339', 'multiple_choice', 'Why does diamond have a very high melting point?', '[{"id":"A","text":"Each carbon atom forms four strong covalent bonds in a giant structure, which take lots of energy to break"},{"id":"B","text":"It has weak forces between small molecules"},{"id":"C","text":"It contains delocalised electrons"},{"id":"D","text":"It is made of ions"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('cd95ddba-2b7a-5cc4-a99f-70633b40d4be', 'A', 'Diamond is a giant covalent structure. Melting it means breaking many strong covalent bonds.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('076a1c39-5cb9-5cb3-88d1-54390b9ebbfc', '72a8f72f-3144-534a-8380-4ecd46618339', 'multiple_choice', 'Magnesium forms Mg²⁺ ions and oxygen forms O²⁻ ions. What is the formula of magnesium oxide?', '[{"id":"A","text":"MgO"},{"id":"B","text":"Mg₂O"},{"id":"C","text":"MgO₂"},{"id":"D","text":"Mg₂O₃"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('076a1c39-5cb9-5cb3-88d1-54390b9ebbfc', 'A', 'The charges +2 and −2 cancel out with one of each ion, so the formula is MgO.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('4889d902-1358-5cca-9dfd-b8bcce09dff7', '72a8f72f-3144-534a-8380-4ecd46618339', 'short_answer', 'Which form of carbon has layers of atoms that slide over each other, making it soft and slippery?', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('4889d902-1358-5cca-9dfd-b8bcce09dff7', array['graphite']::text[], 'In graphite each carbon bonds to three others in layers. The forces between layers are weak, so layers slide.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('5db0d7e6-5d17-5eb6-bb61-37a977c612c1', '72a8f72f-3144-534a-8380-4ecd46618339', 'multiple_choice', 'Why does graphite conduct electricity?', '[{"id":"A","text":"Each carbon atom forms three bonds, leaving one delocalised electron per atom"},{"id":"B","text":"It contains ions that move"},{"id":"C","text":"Its layers are held by strong ionic bonds"},{"id":"D","text":"Carbon is a metal"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('5db0d7e6-5d17-5eb6-bb61-37a977c612c1', 'A', 'The delocalised electrons can move along the layers, carrying charge. Diamond has no free electrons, so it doesn''t conduct.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('2f8dbd87-0c8a-585c-bf9e-32ddf3df3aec', '72a8f72f-3144-534a-8380-4ecd46618339', 'multiple_choice', 'Why do ionic compounds conduct electricity when molten but not when solid?', '[{"id":"A","text":"When molten, the ions are free to move and carry charge"},{"id":"B","text":"When molten, free electrons are released"},{"id":"C","text":"Solid ionic compounds have no charged particles"},{"id":"D","text":"Heating turns the ions into metal atoms"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('2f8dbd87-0c8a-585c-bf9e-32ddf3df3aec', 'A', 'In a solid lattice the ions are held in place. Melting (or dissolving) lets the ions move, so charge can flow.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

-- physics / Energy
insert into public.topics (id, subject_id, slug, name, description, education_stage, sort_order)
select '2d577615-d101-541a-8104-d6293b12340d', id, 'energy', 'Energy', 'Energy stores, calculations, power and efficiency.', 'gcse', 110
from public.subjects where slug = 'physics'
on conflict (id) do update set name = excluded.name, description = excluded.description;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('cd8b0cda-6825-5f66-9dc3-a97338689f6f', '2d577615-d101-541a-8104-d6293b12340d', 'multiple_choice', 'What is the unit of energy?', '[{"id":"A","text":"Joule (J)"},{"id":"B","text":"Watt (W)"},{"id":"C","text":"Newton (N)"},{"id":"D","text":"Volt (V)"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('cd8b0cda-6825-5f66-9dc3-a97338689f6f', 'A', 'Energy is measured in joules. Watts measure power, newtons measure force and volts measure potential difference.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('ddd6fa17-62fc-5bac-8864-d68cb4625849', '2d577615-d101-541a-8104-d6293b12340d', 'multiple_choice', 'Which equation gives kinetic energy?', '[{"id":"A","text":"Eₖ = ½ m v²"},{"id":"B","text":"Eₖ = m g h"},{"id":"C","text":"Eₖ = P t"},{"id":"D","text":"Eₖ = F d"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('ddd6fa17-62fc-5bac-8864-d68cb4625849', 'A', 'Kinetic energy = ½ × mass × speed². m g h gives gravitational potential energy.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('7a1fe794-4a9d-5e75-b87a-2011a5359ece', '2d577615-d101-541a-8104-d6293b12340d', 'true_false', 'True or false: burning fuel creates new energy.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('7a1fe794-4a9d-5e75-b87a-2011a5359ece', 'B', 'Energy can''t be created or destroyed. Burning transfers energy from the fuel''s chemical store to thermal stores.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('fb93f9f1-94bf-5bb3-bf34-2a202e4d37eb', '2d577615-d101-541a-8104-d6293b12340d', 'multiple_choice', 'A 1000 kg car travels at 10 m/s. How much kinetic energy does it have?', '[{"id":"A","text":"50 000 J"},{"id":"B","text":"5000 J"},{"id":"C","text":"100 000 J"},{"id":"D","text":"10 000 J"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('fb93f9f1-94bf-5bb3-bf34-2a202e4d37eb', 'A', 'Eₖ = ½ × 1000 × 10² = 0.5 × 1000 × 100 = 50 000 J. Remember to square the speed.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('fd7986da-e069-5b30-af50-068e97eebcd9', '2d577615-d101-541a-8104-d6293b12340d', 'multiple_choice', 'A 2 kg bag is lifted 5 m. How much gravitational potential energy does it gain? (g = 9.8 N/kg)', '[{"id":"A","text":"98 J"},{"id":"B","text":"10 J"},{"id":"C","text":"49 J"},{"id":"D","text":"980 J"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('fd7986da-e069-5b30-af50-068e97eebcd9', 'A', 'Eₚ = m g h = 2 × 9.8 × 5 = 98 J.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('ea510900-16ef-52cf-8d56-bed0f893d9d1', '2d577615-d101-541a-8104-d6293b12340d', 'short_answer', 'What is the unit of power?', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('ea510900-16ef-52cf-8d56-bed0f893d9d1', array['watt', 'watts', 'w', 'the watt']::text[], 'Power is measured in watts (W). One watt is one joule transferred per second.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('88300168-d89e-5c77-9af8-498d59cc6dcd', '2d577615-d101-541a-8104-d6293b12340d', 'multiple_choice', 'A motor is supplied with 400 J and transfers 300 J usefully. What is its efficiency?', '[{"id":"A","text":"75%"},{"id":"B","text":"133%"},{"id":"C","text":"25%"},{"id":"D","text":"100 J"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('88300168-d89e-5c77-9af8-498d59cc6dcd', 'A', 'Efficiency = useful output ÷ total input = 300 ÷ 400 = 0.75 = 75%. Efficiency can never be above 100%.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('cd18230d-6983-519e-8b1d-2be638221e62', '2d577615-d101-541a-8104-d6293b12340d', 'multiple_choice', 'A 2000 W kettle runs for 60 seconds. How much energy does it transfer?', '[{"id":"A","text":"120 000 J"},{"id":"B","text":"2060 J"},{"id":"C","text":"33 J"},{"id":"D","text":"1200 J"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('cd18230d-6983-519e-8b1d-2be638221e62', 'A', 'Energy = power × time = 2000 × 60 = 120 000 J.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

