on conflict (id) do update set name = excluded.name, description = excluded.description;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('e314a462-f5cb-5f98-840c-4463db7a410e', 'a3c5ac74-d828-52dc-803f-282f01d9bd3b', 'multiple_choice', 'What is the unit of electric current?', '[{"id":"A","text":"Ampere (A)"},{"id":"B","text":"Volt (V)"},{"id":"C","text":"Ohm (Ω)"},{"id":"D","text":"Coulomb (C)"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('e314a462-f5cb-5f98-840c-4463db7a410e', 'A', 'Current is measured in amperes (amps). Charge is measured in coulombs and resistance in ohms.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('e11cda45-aa59-5feb-b61d-500462ce08de', 'a3c5ac74-d828-52dc-803f-282f01d9bd3b', 'multiple_choice', 'Which equation links potential difference (V), current (I) and resistance (R)?', '[{"id":"A","text":"V = I × R"},{"id":"B","text":"V = I ÷ R"},{"id":"C","text":"V = R ÷ I"},{"id":"D","text":"V = I + R"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('e11cda45-aa59-5feb-b61d-500462ce08de', 'A', 'Potential difference = current × resistance. It can be rearranged to I = V ÷ R or R = V ÷ I.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('d134210c-b601-5803-a096-afdfc935b0fc', 'a3c5ac74-d828-52dc-803f-282f01d9bd3b', 'true_false', 'True or false: in a series circuit, the current is the same at every point.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('d134210c-b601-5803-a096-afdfc935b0fc', 'A', 'There is only one path for the charge to flow around, so the current is the same everywhere in a series circuit.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('42c783c1-66ed-54cc-a613-ef2744f84b73', 'a3c5ac74-d828-52dc-803f-282f01d9bd3b', 'multiple_choice', 'A current of 2 A flows through a 6 Ω resistor. What is the potential difference across it?', '[{"id":"A","text":"12 V"},{"id":"B","text":"3 V"},{"id":"C","text":"8 V"},{"id":"D","text":"0.33 V"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('42c783c1-66ed-54cc-a613-ef2744f84b73', 'A', 'V = I × R = 2 × 6 = 12 V.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('9ff05c54-f542-51fc-a148-0fa12ed1642e', 'a3c5ac74-d828-52dc-803f-282f01d9bd3b', 'multiple_choice', 'A current of 3 A flows for 10 s. How much charge flows?', '[{"id":"A","text":"30 C"},{"id":"B","text":"3.3 C"},{"id":"C","text":"13 C"},{"id":"D","text":"0.3 C"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('9ff05c54-f542-51fc-a148-0fa12ed1642e', 'A', 'Charge = current × time: Q = 3 × 10 = 30 C.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('9e7add05-14e5-5cf5-92a7-0f6db2ff9bda', 'a3c5ac74-d828-52dc-803f-282f01d9bd3b', 'short_answer', 'What is the potential difference of UK mains electricity, in volts?', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
