insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('1735eb8a-c27b-53d7-86a2-a36c803352b5', 'a3c5ac74-d828-52dc-803f-282f01d9bd3b', 'multiple_choice', 'A 4 Ω and a 6 Ω resistor are connected in series. What is the total resistance?', '[{"id":"A","text":"10 Ω"},{"id":"B","text":"2.4 Ω"},{"id":"C","text":"24 Ω"},{"id":"D","text":"2 Ω"}]'::jsonb, 'challenge', 'question_bank', true)
