insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('812548c2-dc5b-525d-9ca0-1e3e5af34de8', '6981172b-5887-5aed-a477-dd67d0ff4260', 'true_false', 'True or false: a habitat is the place where an organism lives.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('812548c2-dc5b-525d-9ca0-1e3e5af34de8', 'A', 'A habitat is where an organism lives. A community is all the populations living in that habitat.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('7278804b-bbcb-53ed-915f-71847366a9f7', '6981172b-5887-5aed-a477-dd67d0ff4260', 'multiple_choice', 'Which of these is an abiotic factor?', '[{"id":"A","text":"Light intensity"},{"id":"B","text":"Predators"},{"id":"C","text":"Disease"},{"id":"D","text":"Competition between species"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('7278804b-bbcb-53ed-915f-71847366a9f7', 'A', 'Abiotic factors are non-living, such as light, temperature and water. Predators, disease and competition are biotic (living) factors.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('582acb3d-ce91-5181-944f-26138bf3a99f', '6981172b-5887-5aed-a477-dd67d0ff4260', 'multiple_choice', 'What is a quadrat used for?', '[{"id":"A","text":"Estimating how many of a plant species are in an area"},{"id":"B","text":"Measuring the temperature of soil"},{"id":"C","text":"Catching flying insects"},{"id":"D","text":"Measuring the pH of a pond"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('582acb3d-ce91-5181-944f-26138bf3a99f', 'A', 'Placing quadrats randomly and counting the plants inside lets you estimate the population over a whole area.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('eee62e42-41f6-5f44-88df-b84c5c6e0f9c', '6981172b-5887-5aed-a477-dd67d0ff4260', 'short_answer', 'What word describes all the populations of different species living in a habitat?', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('eee62e42-41f6-5f44-88df-b84c5c6e0f9c', array['community', 'a community']::text[], 'A community is all the populations in a habitat. Together with the non-living parts, it makes an ecosystem.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('f126480f-d425-53d7-aac3-81ec8bbf15d4', '6981172b-5887-5aed-a477-dd67d0ff4260', 'multiple_choice', 'Why is energy lost between trophic levels in a food chain?', '[{"id":"A","text":"Some is used in respiration and movement, and not all of an organism is eaten or digested"},{"id":"B","text":"Energy is destroyed when animals eat"},{"id":"C","text":"Plants absorb energy back from animals"},{"id":"D","text":"Energy only flows from consumers to producers"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('f126480f-d425-53d7-aac3-81ec8bbf15d4', 'A', 'Only a small fraction of biomass passes on. The rest is lost as heat from respiration, in waste, or in parts that aren''t eaten.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('6971c641-e876-53e3-bb9f-300653cd283e', '6981172b-5887-5aed-a477-dd67d0ff4260', 'multiple_choice', 'Which process returns carbon dioxide to the atmosphere?', '[{"id":"A","text":"Respiration"},{"id":"B","text":"Photosynthesis"},{"id":"C","text":"Osmosis"},{"id":"D","text":"Transpiration"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('6971c641-e876-53e3-bb9f-300653cd283e', 'A', 'Respiration by plants, animals and decomposers releases CO₂. Photosynthesis removes it from the air; combustion also releases it.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

-- combined-science / Particles and matter
