from public.subjects where slug = 'combined-science'
on conflict (id) do update set name = excluded.name, description = excluded.description;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('babb885b-a027-5cb1-8a66-4fbd5a8113f5', 'e0fcf23f-7c54-5569-bfc9-34c385dda762', 'multiple_choice', 'In which state are particles closest together, vibrating in fixed positions?', '[{"id":"A","text":"Solid"},{"id":"B","text":"Liquid"},{"id":"C","text":"Gas"},{"id":"D","text":"All three equally"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('babb885b-a027-5cb1-8a66-4fbd5a8113f5', 'A', 'In a solid, particles are tightly packed in a regular pattern and can only vibrate. In a gas they are far apart and move randomly.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('0f0f7067-d9c0-54ec-b31f-d61094846dd4', 'e0fcf23f-7c54-5569-bfc9-34c385dda762', 'multiple_choice', 'What is the change of state from a liquid to a gas called?', '[{"id":"A","text":"Evaporating"},{"id":"B","text":"Condensing"},{"id":"C","text":"Freezing"},{"id":"D","text":"Melting"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('0f0f7067-d9c0-54ec-b31f-d61094846dd4', 'A', 'Evaporating (or boiling) turns a liquid into a gas. Condensing is the reverse: gas to liquid.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('f97e203f-34ce-5c5a-b0c0-88d20de2c34e', 'e0fcf23f-7c54-5569-bfc9-34c385dda762', 'true_false', 'True or false: mass is conserved when ice melts.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('f97e203f-34ce-5c5a-b0c0-88d20de2c34e', 'A', 'Changes of state are physical changes. The particles are rearranged, but none are gained or lost, so mass stays the same.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('51189a35-abd2-578d-8487-cf0270466f0d', 'e0fcf23f-7c54-5569-bfc9-34c385dda762', 'multiple_choice', 'Which equation is used to calculate density?', '[{"id":"A","text":"density = mass ÷ volume"},{"id":"B","text":"density = volume ÷ mass"},{"id":"C","text":"density = mass × volume"},{"id":"D","text":"density = mass − volume"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('51189a35-abd2-578d-8487-cf0270466f0d', 'A', 'Density is mass per unit volume: ρ = m ÷ V.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('055e6bfe-8b9e-5d43-99b8-290dcb1e5f05', 'e0fcf23f-7c54-5569-bfc9-34c385dda762', 'multiple_choice', 'A block has a mass of 400 g and a volume of 50 cm³. What is its density?', '[{"id":"A","text":"8 g/cm³"},{"id":"B","text":"20 000 g/cm³"},{"id":"C","text":"0.125 g/cm³"},{"id":"D","text":"450 g/cm³"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('055e6bfe-8b9e-5d43-99b8-290dcb1e5f05', 'A', 'Density = 400 ÷ 50 = 8 g/cm³.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('27d575b4-ade1-59cf-91b4-a8b68a0c7556', 'e0fcf23f-7c54-5569-bfc9-34c385dda762', 'short_answer', 'What name is given to the energy needed to change the state of 1 kg of a substance without changing its temperature?', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('27d575b4-ade1-59cf-91b4-a8b68a0c7556', array['specific latent heat', 'latent heat', 'the specific latent heat']::text[], 'Specific latent heat (J/kg) is the energy to change the state of 1 kg. It is different for melting (fusion) and boiling (vaporisation).')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('ccc2c8af-5780-543d-bee1-fa85f57d0df1', 'e0fcf23f-7c54-5569-bfc9-34c385dda762', 'multiple_choice', 'Why does the pressure of a gas in a sealed container increase when it is heated?', '[{"id":"A","text":"The particles move faster, hitting the walls more often and with more force"},{"id":"B","text":"The particles get bigger"},{"id":"C","text":"More particles are created"},{"id":"D","text":"The container walls get thinner"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('ccc2c8af-5780-543d-bee1-fa85f57d0df1', 'A', 'Heating increases the particles'' kinetic energy. More frequent, harder collisions with the walls mean higher pressure.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('200e32d2-3e7b-5d37-a6f4-167f4af06583', 'e0fcf23f-7c54-5569-bfc9-34c385dda762', 'multiple_choice', 'The specific latent heat of fusion of ice is 334 000 J/kg. How much energy is needed to melt 2 kg of ice at 0 °C?', '[{"id":"A","text":"668 000 J"},{"id":"B","text":"167 000 J"},{"id":"C","text":"334 002 J"},{"id":"D","text":"336 000 J"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('200e32d2-3e7b-5d37-a6f4-167f4af06583', 'A', 'Energy = mass × specific latent heat = 2 × 334 000 = 668 000 J.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

