insert into public.question_answers (question_id, correct_option, explanation) values ('84fec605-81bd-53eb-8c8e-fe07542ad516', 'A', 'Simpson, a Scottish surgeon, found chloroform made patients unconscious. Lister later introduced carbolic acid as an antiseptic.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('83fd5a64-b57a-52a2-8348-f3fc2c53951e', '8a3c66b2-1c52-5046-8bd0-50ea27b2fa4f', 'short_answer', 'Which doctor linked an 1854 cholera outbreak in London to a water pump on Broad Street?', null, 'standard', 'question_bank', true)
