insert into public.question_answers (question_id, correct_option, explanation) values ('b701bff4-0196-53cb-8d47-78da9f0e0bd9', 'A', 'In 1923 prices rose so fast that money became almost worthless, partly because the government printed money after the French occupied the Ruhr.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('8b4c82ea-b2d8-5b77-9fb8-f8ce49d473fc', 'de0ecb39-7ef5-501e-b3d8-db11119aab6c', 'multiple_choice', 'Which event in February 1933 did the Nazis use as an excuse to arrest communists?', '[{"id":"A","text":"The Reichstag Fire"},{"id":"B","text":"The Munich Putsch"},{"id":"C","text":"The Night of the Long Knives"},{"id":"D","text":"Kristallnacht"}]'::jsonb, 'standard', 'question_bank', true)
