insert into public.question_answers (question_id, correct_option, explanation) values ('8b4c82ea-b2d8-5b77-9fb8-f8ce49d473fc', 'A', 'A Dutch communist was blamed for the fire. Hitler used it to persuade Hindenburg to pass emergency decrees.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('e1381ae3-5eb8-5891-8854-cab0ad2d88d8', 'de0ecb39-7ef5-501e-b3d8-db11119aab6c', 'multiple_choice', 'What did the Enabling Act of March 1933 allow Hitler to do?', '[{"id":"A","text":"Pass laws without the approval of the Reichstag"},{"id":"B","text":"Become President as well as Chancellor"},{"id":"C","text":"Leave the League of Nations"},{"id":"D","text":"Join with Austria"}]'::jsonb, 'standard', 'question_bank', true)
