insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('f6650060-5d18-5142-b974-2ce45d0bb753', 'de0ecb39-7ef5-501e-b3d8-db11119aab6c', 'multiple_choice', 'What did Article 48 of the Weimar Constitution allow?', '[{"id":"A","text":"The President to rule by decree in an emergency"},{"id":"B","text":"The Chancellor to ban all other parties"},{"id":"C","text":"Women to vote for the first time"},{"id":"D","text":"Germany to rebuild its army"}]'::jsonb, 'challenge', 'question_bank', true)
