from public.subjects where slug = 'geography'
on conflict (id) do update set name = excluded.name, description = excluded.description;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('75f10318-fa80-50d5-b521-8f5aaa1c3cad', 'ecd2c101-e723-5ebd-a8c1-6dc129f7b045', 'multiple_choice', 'At which type of plate margin do plates move apart?', '[{"id":"A","text":"Constructive"},{"id":"B","text":"Destructive"},{"id":"C","text":"Conservative"},{"id":"D","text":"Collision"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('75f10318-fa80-50d5-b521-8f5aaa1c3cad', 'A', 'At constructive margins plates move apart and magma rises to form new crust, as at the Mid-Atlantic Ridge.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('b87ea107-c86a-5ebb-a13e-33d5c4694c24', 'ecd2c101-e723-5ebd-a8c1-6dc129f7b045', 'multiple_choice', 'Which instrument is used to detect and record earthquakes?', '[{"id":"A","text":"Seismometer"},{"id":"B","text":"Barometer"},{"id":"C","text":"Anemometer"},{"id":"D","text":"Thermometer"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('b87ea107-c86a-5ebb-a13e-33d5c4694c24', 'A', 'A seismometer records ground shaking. A barometer measures air pressure and an anemometer measures wind speed.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('a82f2e98-93e6-5b6a-8159-030f9b7062e6', 'ecd2c101-e723-5ebd-a8c1-6dc129f7b045', 'true_false', 'True or false: volcanoes can form at constructive plate margins.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('a82f2e98-93e6-5b6a-8159-030f9b7062e6', 'A', 'Magma rises where plates move apart, forming gently sloping shield volcanoes, such as those in Iceland.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('ef6e924a-bfb9-5091-9663-53dac7200737', 'ecd2c101-e723-5ebd-a8c1-6dc129f7b045', 'multiple_choice', 'Why do many people choose to live near volcanoes?', '[{"id":"A","text":"Volcanic soils are very fertile for farming"},{"id":"B","text":"Volcanoes never erupt more than once"},{"id":"C","text":"Land near volcanoes is always flat"},{"id":"D","text":"There are no earthquakes near volcanoes"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('ef6e924a-bfb9-5091-9663-53dac7200737', 'A', 'Fertile soils, tourism, geothermal energy and minerals all attract people, despite the risk of eruptions.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('6b0f8303-e814-5b9f-8b08-391606215f3b', 'ecd2c101-e723-5ebd-a8c1-6dc129f7b045', 'multiple_choice', 'What happens at a conservative plate margin?', '[{"id":"A","text":"Plates slide past each other"},{"id":"B","text":"Plates move apart"},{"id":"C","text":"An oceanic plate sinks under a continental plate"},{"id":"D","text":"Plates stop moving completely"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('6b0f8303-e814-5b9f-8b08-391606215f3b', 'A', 'At conservative margins plates slide past each other. Friction builds up and is released as earthquakes, as on the San Andreas Fault.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('cfcf2fa5-30c2-5e8a-867c-06aad1ecec2b', 'ecd2c101-e723-5ebd-a8c1-6dc129f7b045', 'short_answer', 'What is the point on the Earth''s surface directly above the focus of an earthquake called?', null, 'standard', 'question_bank', true)
