on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('9551112c-6fdf-5900-8e4c-3ab8776ae7c2', 'ecd2c101-e723-5ebd-a8c1-6dc129f7b045', 'multiple_choice', 'Why do earthquakes in lower-income countries often cause more deaths than similar earthquakes in higher-income countries?', '[{"id":"A","text":"Buildings are less likely to be earthquake-resistant and emergency services may be less well prepared"},{"id":"B","text":"Earthquakes there are always stronger"},{"id":"C","text":"People there live further from plate margins"},{"id":"D","text":"Seismometers don''t work there"}]'::jsonb, 'challenge', 'question_bank', true)
