insert into public.question_answers (question_id, correct_option, explanation) values ('9551112c-6fdf-5900-8e4c-3ab8776ae7c2', 'A', 'Building standards, preparation, emergency response and healthcare all reduce deaths. These often depend on money and resources.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('c1638cc3-7639-5ada-8d62-b0040c517507', 'ecd2c101-e723-5ebd-a8c1-6dc129f7b045', 'multiple_choice', 'Tropical storms usually form over oceans with a surface temperature of at least about…', '[{"id":"A","text":"27 °C"},{"id":"B","text":"10 °C"},{"id":"C","text":"17 °C"},{"id":"D","text":"37 °C"}]'::jsonb, 'challenge', 'question_bank', true)
