insert into public.question_answers (question_id, correct_option, explanation) values ('e9dbfd9f-a84a-525a-8eb8-daa812c3c799', 'A', 'The source is where a river begins, often in hills or mountains. The mouth is where it meets the sea.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('713f7eb5-bb85-59e9-8fe4-826ceacf9417', '5c9bb700-c4b0-52f7-8d50-17b27d29d51d', 'multiple_choice', 'What is a smaller river that joins a larger river called?', '[{"id":"A","text":"A tributary"},{"id":"B","text":"A meander"},{"id":"C","text":"A delta"},{"id":"D","text":"An estuary"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('713f7eb5-bb85-59e9-8fe4-826ceacf9417', 'A', 'A tributary flows into a larger river. The point where they meet is called a confluence.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('022c6893-0869-5e91-96dd-f3ed4190217c', '5c9bb700-c4b0-52f7-8d50-17b27d29d51d', 'true_false', 'True or false: deposition happens when a river loses energy.', '[{"id":"A","text":"True"},{"id":"B","text":"False"}]'::jsonb, 'foundation', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('022c6893-0869-5e91-96dd-f3ed4190217c', 'A', 'When a river slows down, for example on the inside of a bend or at its mouth, it drops the material it was carrying.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('d84f115b-500b-53a8-ad78-06627c3f7372', '5c9bb700-c4b0-52f7-8d50-17b27d29d51d', 'multiple_choice', 'Which erosion process happens when rocks carried by the river wear away the bed and banks?', '[{"id":"A","text":"Abrasion"},{"id":"B","text":"Attrition"},{"id":"C","text":"Hydraulic action"},{"id":"D","text":"Solution"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('d84f115b-500b-53a8-ad78-06627c3f7372', 'A', 'Abrasion is rocks scraping the bed and banks. Attrition is rocks hitting each other and becoming smaller and rounder.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('f926e959-3b8b-5812-b3b5-3a62aa9e948f', '5c9bb700-c4b0-52f7-8d50-17b27d29d51d', 'multiple_choice', 'How does a waterfall form?', '[{"id":"A","text":"A band of hard rock lies over softer rock, which erodes faster and undercuts the hard rock"},{"id":"B","text":"A river flows uphill"},{"id":"C","text":"Deposition builds up a wall of rock"},{"id":"D","text":"A glacier melts into the river"}]'::jsonb, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('f926e959-3b8b-5812-b3b5-3a62aa9e948f', 'A', 'The soft rock erodes to form an overhang and a plunge pool. The overhang collapses, and the waterfall retreats upstream, forming a gorge.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('43b01b47-efed-59ca-bc08-4f18d24bf500', '5c9bb700-c4b0-52f7-8d50-17b27d29d51d', 'short_answer', 'What is a crescent-shaped lake formed when a meander is cut off from the river called?', null, 'standard', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, accepted_answers, explanation) values ('43b01b47-efed-59ca-bc08-4f18d24bf500', array['ox-bow lake', 'oxbow lake', 'ox bow lake', 'ox-bow', 'oxbow']::text[], 'Erosion narrows the meander''s neck until the river breaks through. Deposition then seals off the old loop as an ox-bow lake.')
on conflict (question_id) do update set accepted_answers = excluded.accepted_answers, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('abad3c20-1b83-55c8-ab71-5c7a71d063f5', '5c9bb700-c4b0-52f7-8d50-17b27d29d51d', 'multiple_choice', 'Why does a river''s velocity often increase downstream, even though the gradient gets less steep?', '[{"id":"A","text":"The channel gets wider and deeper, so a smaller share of the water touches the bed and banks, reducing friction"},{"id":"B","text":"The water gets colder"},{"id":"C","text":"Tributaries make the river shallower"},{"id":"D","text":"Gravity is stronger near the sea"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('abad3c20-1b83-55c8-ab71-5c7a71d063f5', 'A', 'A larger, smoother channel is more efficient: less energy is lost to friction, so the water can flow faster.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;
insert into public.questions (id, topic_id, question_type, question_text, options, difficulty, source_type, is_published) values ('58f95332-05d1-555d-af78-4dd71bfcd6bb', '5c9bb700-c4b0-52f7-8d50-17b27d29d51d', 'multiple_choice', 'Which of these is a hard engineering flood defence?', '[{"id":"A","text":"Building embankments"},{"id":"B","text":"Planting trees in the drainage basin"},{"id":"C","text":"Floodplain zoning"},{"id":"D","text":"Restoring the river''s meanders"}]'::jsonb, 'challenge', 'question_bank', true)
on conflict (id) do update set question_text = excluded.question_text, options = excluded.options, difficulty = excluded.difficulty;
insert into public.question_answers (question_id, correct_option, explanation) values ('58f95332-05d1-555d-af78-4dd71bfcd6bb', 'A', 'Hard engineering uses built structures such as embankments, dams and flood walls. The other options are soft engineering.')
on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation;

